function encode(num) {
  // Skip whole groups of equal-length strings, then write the offset inside the group with leading zeros.
  let length = 0;
  let offset = num;
  while (offset >= 2 ** length) {
    offset -= 2 ** length;
    length++;
  }
  if (length === 0) return '';
  let text = '';
  for (let i = 0; i < length; i++) {
    text = String(offset % 2) + text;
    offset = Math.floor(offset / 2);
  }
  return text;
}

